-- =============================================================================
-- DATOS DE PRUEBA: ruta del vehiculo LXWP75 (Pudahuel -> Providencia)
-- =============================================================================
--
-- Crea:
--   1. El vehiculo LXWP75 (codigo de flota TEST-LXWP75) y un conductor de
--      prueba.
--   2. Una ruta "en_curso" con 6 paradas, en orden geografico de oeste a
--      este: 5 en Pudahuel y la ultima en Providencia.
--   3. Los clientes de cada parada (no existe una tabla de clientes propia:
--      en este esquema el cliente vive denormalizado en paradas_ruta,
--      porque el cliente real sigue viviendo en el ERP de Fenice).
--   4. 5 alertas de categorias distintas (ruta, geocerca, operacion) sobre
--      esa misma ruta.
--
-- El trazado planificado (trazado_planificado) NO conecta las paradas en
-- linea recta: es el trayecto real por calles calculado con OSRM
-- (router.project-osrm.org) a traves de las 6 paradas en orden: ~41.4 km y
-- 1270 puntos siguiendo el trazado vial real. La misma capacidad para
-- calcular esto quedo disponible en la aplicacion en planDrivingRoute()
-- (src/services/eta/eta-service.ts) y expuesta en POST /api/rutas/planificar,
-- para cuando se cree o importe una ruta real.
--
-- Estado de las 6 paradas: 2 completadas, 4 pendientes (tal como se pidio).
-- La parada 2 llega con demora (33 min), y hay una alerta que lo explica.
--
-- Todo queda identificable por el prefijo TEST-LXWP75 / test-lxwp75-, para
-- poder borrarlo limpio despues con lxwp75-borrar.sql.
--
-- Seguro de re-ejecutar: usa upsert (on conflict) en vehiculo/conductor/ruta,
-- y limpia sus propias paradas y alertas antes de volver a insertarlas.
--
-- Ejecutar completo en el editor SQL de Supabase (o via psql) contra la
-- misma base que usa la aplicacion.
-- =============================================================================

do $$
declare
  v_vehiculo_id  uuid;
  v_conductor_id uuid;
  v_ruta_id      uuid;
begin

  -- 1. Vehiculo -----------------------------------------------------------
  insert into vehiculos (
    patente, codigo_flota, marca, modelo, anio, tipo,
    capacidad_litros, compartimentos, base_despacho, activo
  ) values (
    'LXWP75', 'TEST-LXWP75', 'Volvo', 'FH 460 6x4', 2022, 'cisterna_semirremolque',
    36000, 3, 'Terminal Pudahuel (prueba)', true
  )
  on conflict (patente) do update set
    codigo_flota = excluded.codigo_flota,
    activo = true
  returning id into v_vehiculo_id;

  -- 2. Conductor de prueba --------------------------------------------------
  insert into conductores (
    nombre_completo, documento_identidad, telefono, clase_licencia,
    licencia_vencimiento, activo
  ) values (
    'Conductor de Prueba LXWP75', 'TEST-LXWP75-RUT', '+56 9 0000 0000', 'A5',
    (current_date + interval '2 years')::date, true
  )
  on conflict (documento_identidad) do update set
    nombre_completo = excluded.nombre_completo,
    activo = true
  returning id into v_conductor_id;

  update vehiculos set conductor_id = v_conductor_id where id = v_vehiculo_id;

  -- 3. Ruta -------------------------------------------------------------
  -- trazado_planificado: trayecto REAL por calles (OSRM), no linea recta
  -- entre paradas. Ver nota al inicio del archivo.
  insert into rutas (
    codigo, nombre, fecha, vehiculo_id, conductor_id, estado,
    comunas_autorizadas, trazado_planificado, trazado_ejecutado,
    distancia_planificada_km, iniciada_at
